const insideWalls=[];function clearInterior(){while(indoor.children.length){const c=indoor.children[0];indoor.remove(c);c.traverse(n=>{if(n.geometry)n.geometry.dispose();if(n.material?.map){n.material.map.dispose();n.material.dispose();}});}insideWalls.length=0;}
const books=[{title:'The art of slowing down',text:'Some days, the nicest thing you can do is leave a little room.\n\nRoom for a long walk. Room for one more chapter. Room to watch the light change on the water.\n\nYou don’t have to turn every beautiful thing into something useful.'},{title:'A place of your own',text:'A library beside the sea. Pink flowers outside the window. A desk with nothing on it but an open notebook.\n\nMaybe a little world starts with the things you love, gathered in one place.'},{title:'Letters from the coast',text:'I took the long way home today.\n\nPast the waterfall, through the square, all the way down to the beach. The sky was pink by the time I got there.\n\nI think I’ll take the long way tomorrow, too.'}];
function shelf(x,z,rot=0){const g=group(x,.5,z,indoor);g.rotation.y=rot;box(4.4,4,.2,'#ae7a83',0,2,-.4,g);for(const xx of [-2.2,2.2])box(.15,4,.9,'#af7b82',xx,2,0,g);for(let y=.25;y<4;y+=1.1){box(4.5,.12,1,'#f0cfb8',0,y,0,g);for(let j=0;j<13;j++){const h=.5+rnd()*.43;box(.17+rnd()*.08,h,.5,['#9e779e','#d8879a','#c6b98c','#93b1b1','#e5b8c2'][j%5],-1.93+j*.31,y+h/2+.06,0,g);}}insideWalls.push({x,z,w:rot?1.5:5,d:rot?5:1.5});}
function setupInterior(b){clearInterior();box(24,.4,20,'#ead2b9',0,.25,0,indoor);box(24,7,.3,b.kind==='studio'?'#dac8de':'#eec2ca',0,3.7,-10,indoor);box(.3,7,20,'#edc4cb',-12,3.7,0,indoor);box(.3,7,20,'#f7dbd6',12,3.7,0,indoor);for(let i=-11;i<12;i++)box(.025,.01,20,'#cead9e',i,.475,0,indoor);box(8,.02,8,'#c17b9c',0,.495,0,indoor);for(const x of [-6,6]){box(3.6,3.5,.2,'#fff1db',x,4,-9.77,indoor);box(3.2,3.1,.2,'#91c0c6',x,4,-9.6,indoor);box(.12,3.2,.22,'#fff1db',x,4,-9.45,indoor);box(3.2,.12,.22,'#fff1db',x,4,-9.45,indoor);}label(b.name,0,7.4,-8,10,indoor);label('Outside',0,1.5,9,4,indoor);
if(b.kind==='library'){for(const x of [-8,-2,4,9])shelf(x,-7.8);shelf(-10,0,Math.PI/2);shelf(10,0,Math.PI/2);cylinder(2.2,2.2,.2,'#c99092',0,1.7,-1,indoor);cylinder(.25,.4,1.2,'#aa7a80',0,1,-1,indoor);insideWalls.push({x:0,z:-1,w:4.8,d:4.8});for(let i=0;i<3;i++)box(.7,.16,1,'#b176a3',-.9+i*.85,1.9,-1,indoor);label('E · Pick a book',0,3,-1,5,indoor);for(const x of [-4,4]){box(1.5,.6,1.5,'#dfa7b9',x,.8,2,indoor);box(1.5,1.2,.3,'#dfa7b9',x,1.4,2.6,indoor);}}
if(b.kind==='cafe'){box(17,2,2,'#ba7993',0,1.5,-6.5,indoor);box(17.4,.2,2.5,'#f5dfc2',0,2.55,-6.5,indoor);insideWalls.push({x:0,z:-6.5,w:18,d:3});for(const x of [-6,0,6]){cylinder(.32,.27,.55,'#fff5df',x,2.93,-6.2,indoor);cylinder(1.3,1.3,.12,'#d7a594',x,1.35,1,indoor);cylinder(.13,.3,.9,'#936c79',x,.9,1,indoor);insideWalls.push({x,z:1,w:3,d:3});}label('E · A moment to pause',0,4,-5,7,indoor);}
if(b.kind==='studio'){box(9,1.3,2.5,'#bf90aa',0,1.15,-5,indoor);box(9.3,.2,2.8,'#f6e2d1',0,1.85,-5,indoor);box(3,1.9,.15,'#654d6d',0,3,-5.5,indoor);box(2.65,1.5,.16,'#dea2bf',0,3,-5.38,indoor);insideWalls.push({x:0,z:-5,w:10,d:3.5});label('E · Meet Krishnasri',0,5,-5,7,indoor);shelf(-9,-7);box(3,4,.2,'#f8edda',8,3,-9.7,indoor);ball(1,'#d292b2',8,3,-9.3,indoor);}}
let playing=false,driving=false,inside=null,speed=0,yaw=0,pitch=.06,zoom=4.6,nearest=null,jumpHeight=0,jumpVelocity=0,sprint=false,quiet=matchMedia('(prefers-reduced-motion: reduce)').matches,bookIndex=0;const keys=new Set(),target=new T.Vector3(),footVelocity=new T.Vector3();let toastTimer;
$('motion').checked=quiet;function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function start(){closeCharacterView();playing=true;document.body.classList.remove('in-lobby');girl.g.rotation.y=Math.PI;yaw=0;pitch=.06;zoom=4.6;$('welcome').hidden=true;$('playHud').hidden=false;$('world').focus();toast('WASD to move · Drag to look · Space to jump · E to interact · C for character close-up');}
function blocked(x,z,r=0.5){if(inside){if(Math.abs(x)>11-r||Math.abs(z)>9-r)return true;return insideWalls.some(o=>Math.abs(x-o.x)<o.w/2+r&&Math.abs(z-o.z)<o.d/2+r);}if((x/61)**2+(z/44)**2>1)return true;if(town.blocks(x,z,driving?car.g.rotation.y:girl.g.rotation.y,driving,r))return true;return obstacles.some(o=>Math.abs(x-o.x)<o.w/2+r&&Math.abs(z-o.z)<o.d/2+r);}
function move(g,dx,dz,r){let collided=false;const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.35)),sx=dx/steps,sz=dz/steps;for(let i=0;i<steps;i++){if(!blocked(g.position.x+sx,g.position.z,r))g.position.x+=sx;else collided=true;if(!blocked(g.position.x,g.position.z+sz,r))g.position.z+=sz;else collided=true;}if(collided&&driving)speed*=.62;return !collided;}
function enter(b){if(driving)return;inside=b;outdoor.visible=false;car.g.visible=false;setupInterior(b);indoor.visible=true;girl.g.position.set(0,.5,6);girl.g.rotation.y=Math.PI;speed=0;yaw=0;pitch=.06;zoom=4.2;jumpHeight=0;jumpVelocity=0;$('place').textContent=b.name;toast('Walk around. Press E near the table or shelves to interact.');}
function leave(){const b=inside;inside=null;indoor.visible=false;outdoor.visible=true;car.g.visible=true;girl.g.position.copy(b.door);girl.g.position.z+=1;yaw=0;pitch=.06;zoom=4.6;jumpHeight=0;jumpVelocity=0;toast('Back in the sunshine.');}
function dismount(){const a=car.g.rotation.y;for(const side of [1,-1]){const x=car.g.position.x+Math.cos(a)*2*side,z=car.g.position.z-Math.sin(a)*2*side;if(!blocked(x,z,.45)&&town.safeSpot(x,z)){driving=false;speed=0;footVelocity.set(0,0,0);girl.g.visible=true;girl.g.position.set(x,.5,z);girl.g.rotation.y=a;return;}}toast('Wait for traffic and find a little more space to park.');}
function readStory(title,text,labelText='FROM THE ROSE LIBRARY'){releaseLook();keys.clear();$('storyTitle').textContent=title;$('storyText').textContent=text;$('storyLabel').textContent=labelText;$('storyDialog').showModal();}
function interact(){if(!playing||document.querySelector('dialog[open]'))return;if(driving){dismount();return;}if(!nearest)return;if(nearest.type==='car'){driving=true;jumpHeight=0;jumpVelocity=0;footVelocity.set(0,0,0);girl.g.visible=false;speed=0;yaw=car.g.rotation.y+Math.PI;toast('W/S to drive · A/D to steer · E to get out');}if(nearest.type==='building')enter(nearest.b);if(nearest.type==='exit')leave();if(nearest.type==='read'){const b=books[bookIndex++%books.length];readStory(b.title,b.text);}if(nearest.type==='coffee')readStory('Stay a little longer.','Find a seat by the window. There is no rush here.\n\nWatch the sunset, take a breath, and enjoy a quiet moment in your little corner of the world.','SUNSET CAFÉ');if(nearest.type==='about')readStory('Hi, I’m Krishnasri.','I’m a CSE–AIML student at MRECW. I like creating things, getting lost in libraries, and finding a beautiful view.\n\nThis little world brings my favorite places together: pink streets, mountain air, waterfalls, and the sea.','MY LITTLE STUDIO');}
function updateNearest(){nearest=null;const p=girl.g.position;if(driving){$('action').hidden=false;$('action').textContent='E · Park & get out';return;}if(inside){if(p.z>6)nearest={type:'exit',text:'E · Step outside'};else if(inside.kind==='library'&&(p.z<2||Math.abs(p.x)>7))nearest={type:'read',text:'E · Read a book'};else if(inside.kind==='cafe'&&p.z<-2)nearest={type:'coffee',text:'E · Take a quiet moment'};else if(inside.kind==='studio'&&p.z<0)nearest={type:'about',text:'E · Meet Krishnasri'};}else{if(p.distanceTo(car.g.position)<3.8)nearest={type:'car',text:'E · Get in the pink car'};for(const b of buildings)if(p.distanceTo(b.door)<3)nearest={type:'building',b,text:`E · Enter ${b.name}`};}$('action').hidden=!nearest;if(nearest)$('action').textContent=nearest.text;}
function reset(){closeCharacterView();if(inside)leave();driving=false;speed=0;footVelocity.set(0,0,0);car.g.position.set(2,.5,6);car.g.rotation.y=-.3;girl.g.visible=true;girl.g.position.set(-3,.5,4);yaw=0;pitch=.06;zoom=4.6;jumpHeight=0;jumpVelocity=0;toast('Back in Cherry Blossom Square.');}
const destinations=[{name:'Cherry Blossom Square',x:-3,z:4},{name:'The Rose Library',x:-18,z:-2},{name:'Sunset Café',x:19,z:-2},{name:'My little studio',x:3,z:-21},{name:'Whisper Falls',x:-36,z:-20},{name:'Sunset beach',x:0,z:30}];
function travel(i){if(!Number.isInteger(i)||i<0||i>=destinations.length)throw new Error('Unknown destination');closeCharacterView();if(!playing)start();if(inside)leave();driving=false;speed=0;jumpHeight=0;jumpVelocity=0;girl.g.visible=true;const d=destinations[i];girl.g.position.set(d.x,.5,d.z);$('mapDialog').close();toast(d.name);return {place:d.name};}
function drawMap(){const ctx=$('mapCanvas').getContext('2d'),W=700,H=400;ctx.clearRect(0,0,W,H);ctx.fillStyle='#aed0d0';ctx.fillRect(0,0,W,H);const mx=x=>350+x*4.6,mz=z=>195+z*3.7;ctx.fillStyle='#ebcdad';ctx.beginPath();ctx.ellipse(350,195,295,179,0,0,TAU);ctx.fill();ctx.fillStyle='#b9c399';ctx.beginPath();ctx.ellipse(350,165,258,133,0,0,TAU);ctx.fill();ctx.strokeStyle='#dcaba8';ctx.lineWidth=15;ctx.beginPath();roadCurve.getPoints(100).forEach((p,i)=>i?ctx.lineTo(mx(p.x),mz(p.z)):ctx.moveTo(mx(p.x),mz(p.z)));ctx.closePath();ctx.stroke();for(const b of buildings){ctx.fillStyle='#c37c99';ctx.fillRect(mx(b.x-b.w/2),mz(b.z-b.d/2),b.w*4.6,b.d*3.7);}ctx.font='14px Arial';ctx.textAlign='center';for(const d of destinations){ctx.fillStyle='#5a354f';ctx.fillText(d.name,mx(d.x),mz(d.z)+18);}const p=inside?inside.door:driving?car.g.position:girl.g.position;ctx.fillStyle='#ad285e';ctx.beginPath();ctx.arc(mx(p.x),mz(p.z),7,0,TAU);ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=3;ctx.stroke();}
for(let i=0;i<destinations.length;i++){const b=document.createElement('button');b.textContent=destinations[i].name;b.onclick=()=>travel(i);$('destinations').append(b);}function openMap(){releaseLook();keys.clear();drawMap();$('mapDialog').showModal();}
$('start').onclick=start;$('mapButton').onclick=openMap;$('helpButton').onclick=()=>{releaseLook();keys.clear();$('helpDialog').showModal();};$('reset').onclick=reset;$('action').onclick=interact;$('touchAction').onclick=interact;$('motion').onchange=e=>quiet=e.target.checked;document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{$('world').focus();keys.clear();}));
addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||/INPUT|TEXTAREA/.test(e.target.tagName))return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(e.repeat&&['e','enter','m','r',' ','v','c'].includes(k))return;if(k==='c'){toggleCharacterView();return;}if(characterView){if(k==='escape')toggleCharacterView();return;}if(k==='e'||k==='enter')interact();else if(k==='m')openMap();else if(k==='r')reset();else if(k===' ')jump();else if(k==='v')lockLook();else keys.add(k);});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.key));}
let drag=null,showcaseYaw=0,stickInput={x:0,y:0};
function releaseLook(){if(document.pointerLockElement)document.exitPointerLock?.();}
async function lockLook(){if(!playing)start();if(document.pointerLockElement){releaseLook();return;}try{await $('world').requestPointerLock();}catch{toast('Drag the scene to look around.');}}
$('lookButton').onclick=lockLook;
function rotateLook(dx,dy){if(!playing){showcaseYaw-=dx*.004;return;}yaw-=dx*.004;pitch=T.MathUtils.clamp(pitch+dy*.0018,-.12,.33);}
$('world').onpointerdown=e=>{if(document.pointerLockElement)return;drag={x:e.clientX,y:e.clientY,id:e.pointerId};$('world').setPointerCapture(e.pointerId);};
$('world').onpointermove=e=>{if(document.pointerLockElement===$('world')){rotateLook(e.movementX,e.movementY);return;}if(!drag||drag.id!==e.pointerId)return;rotateLook(e.clientX-drag.x,e.clientY-drag.y);drag={x:e.clientX,y:e.clientY,id:e.pointerId};};
$('world').onpointerup=$('world').onpointercancel=()=>drag=null;
$('world').addEventListener('wheel',e=>{e.preventDefault();zoom=T.MathUtils.clamp(zoom+e.deltaY*.006,3.5,7.5);},{passive:false});
function updateStick(e){if(characterView)closeCharacterView();const r=$('joystick').getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/42,y=(e.clientY-r.top-r.height/2)/42;const l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}stickInput={x,y};$('stick').style.transform=`translate(${x*31}px,${y*31}px)`;}
let stickId=null;$('joystick').onpointerdown=e=>{e.preventDefault();stickId=e.pointerId;$('joystick').setPointerCapture(e.pointerId);updateStick(e);};$('joystick').onpointermove=e=>{if(e.pointerId===stickId)updateStick(e);};
function clearStick(){stickId=null;stickInput={x:0,y:0};$('stick').style.transform='';}
for(const event of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(event,clearStick);
addEventListener('blur',()=>{clearStick();drag=null;});document.addEventListener('visibilitychange',()=>{clearStick();drag=null;});
function jump(){if(playing&&!driving&&!characterView&&jumpHeight===0&&!document.querySelector('dialog[open]'))jumpVelocity=6.4;}
$('jumpButton').onclick=jump;$('runButton').onclick=()=>{sprint=!sprint;$('runButton').setAttribute('aria-pressed',String(sprint));$('runButton').textContent=sprint?'Walk':'Run';};
